#!/usr/bin/env python3
from flask import Flask, render_template, request, send_file
import subprocess
import os
from datetime import datetime

app = Flask(__name__)

def get_espeak_voices():
    result = subprocess.run(['espeak', '--voices'], capture_output=True, text=True)
    voices = []
    for line in result.stdout.split('\n')[1:]:
        if line.strip():
            parts = line.split()
            voice_code = parts[1]
            language = ' '.join(parts[3:-2]).strip()
            voices.append((voice_code, language))
    return voices

@app.route('/')
def index():
    voices = get_espeak_voices()
    return render_template('index.html', voices=voices)

@app.route('/synthesize', methods=['POST'])
def synthesize():
    text = request.form['text']
    voice = request.form['voice']
    home_dir = os.path.expanduser('~')
    timestamp = datetime.now().strftime("%Y%m%d%H%M%S")
    filename = f"tts_{timestamp}.wav"
    filepath = os.path.join(home_dir, filename)

    subprocess.run(['espeak', '-v', voice, '-w', filepath, text])
    return {'filename': filename}

@app.route('/download/<filename>')
def download(filename):
    home_dir = os.path.expanduser('~')
    return send_file(os.path.join(home_dir, filename), mimetype='audio/wav')

if __name__ == '__main__':
    app.run(debug=True)
```

