<script>
const canvas = document.createElement('canvas');
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Initial cube
const initialVertices = [
  [0, 0, 0], [0, 1, 0], [1, 1, 0], [1, 0, 0],
  [0, 0, 1], [0, 1, 1], [1, 1, 1], [1, 0, 1]
];
const initialEdges = [
  [0,1], [1,2], [2,3], [3,0],
  [4,5], [5,6], [6,7], [7,4],
  [0,4], [1,5], [2,6], [3,7]
];

function generateSubdividedCube(levels) {
  let vertices = [...initialVertices];
  let edges = [...initialEdges];

  for (let i = 0; i < levels; i++) {
    const newEdges = [];
    const currentVertices = [...vertices];

    edges.forEach(edge => {
      const a = currentVertices[edge[0]];
      const b = currentVertices[edge[1]];
      const midpoint = a.map((_, i) => (a[i] + b[i])/2);
      const newIndex = vertices.length;

      vertices.push(midpoint);
      newEdges.push([edge[0], newIndex], [newIndex, edge[1]]);
    });

    edges = newEdges;
  }

  return { vertices, edges };
}

const { vertices, edges } = generateSubdividedCube(CONFIG.subdivisionLevel);

let angleX = 0, angleY = 0, angleZ = 0;
let hueShift = 0;

function rotate(axis, angle) {
  const c = Math.cos(angle), s = Math.sin(angle);
  return {
    x: [[1,0,0], [0,c,-s], [0,s,c]],
    y: [[c,0,s], [0,1,0], [-s,0,c]],
    z: [[c,-s,0], [s,c,0], [0,0,1]]
  }[axis];
}

function fractalDisplacement(vertex], freq, amp, octaves) {
  let [x,y,z] = vertex;
  for (let i = 0; i < octaves; i++) {
    const factor = 2**i;
    x += Math.cos(x * freq * factor) * amp / factor;
    y += Math.cos(y * freq * factor) * amp / factor;
    z += Math.cos(z * freq * factor) * amp / factor;
