  return [x,y,z];
}

function project(vertex) {
  const [x,y,z] = vertex;
  const scaledX = (x - CONFIG.offsetX) * CONFIG.scale;
  const scaledY = (y - CONFIG.offsetY) * CONFIG.scale;
  const scaledZ = z * CONFIG.scale;

  const depth = CONFIG.zoom - scaledZ;
  const perspective = CONFIG.zoom / depth;

  return [
    scaledX * perspective + canvas.width/2,
    scaledY * perspective + canvas.height/2
